        browser.alarms.clearAll();
        let alarmInfo = { when: Date.now() + 250 };
        if (option === null)
            option = this.settings.profile.interval.option;
        if (option != IntervalOption.None) {
            if (option === IntervalOption.Custom) {
                if (!this.settings.profile.interval.min || !this.settings.profile.interval.max)
                    return;
                let interval = Math.random() * (this.settings.profile.interval.max * 60 * 1000 - this.settings.profile.interval.min * 60 * 1000) + this.settings.profile.interval.min * 60 * 1000;
                /*
                  Use regular timeout for custom interval
